/* Translate new text automatically. `store_localization.auto_translate` (part 136's table): Settings › Markets and languages' switch "Translate changes automatically", false unless the store turns it on; with it on, a job each hour (/api/cron/translations) has Storelib AI translate the website's text that is new or changed since it was last translated, into each of the store's languages, and puts it live. A translation the merchant wrote or edited is never replaced. `store_localization.auto_translate_run`: what the last run did (when, how many, how many are left, and a short reason when it could not), an object, small, so the switch can say it. Server only, as the table already is. No rows change. Skips itself with a notice where the table is not there (run 136 first). Until it runs, the switch says it needs this part and stays off. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_localization') IS NULL THEN RAISE NOTICE 'automatic translation: store_localization is not there yet, run part 136 first.'; ELSE ALTER TABLE public.store_localization ADD COLUMN IF NOT EXISTS auto_translate boolean NOT NULL DEFAULT false; ALTER TABLE public.store_localization ADD COLUMN IF NOT EXISTS auto_translate_run jsonb NOT NULL DEFAULT '{}'::jsonb; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'store_localization_auto_translate_run_small') THEN ALTER TABLE public.store_localization ADD CONSTRAINT store_localization_auto_translate_run_small CHECK (jsonb_typeof(auto_translate_run) = 'object' AND pg_column_size(auto_translate_run) < 2048) NOT VALID; END IF; CREATE INDEX IF NOT EXISTS idx_store_localization_auto_translate ON public.store_localization (creator_id) WHERE auto_translate; END IF; END $do$;
notify pgrst, 'reload schema';
